#include "runtime/interpreter.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
int main(){using namespace penta;unsigned checks=0,failures=0;runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-mixed-fem-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));options.odeCacheDirectory=options.dataDirectory/"cache/odes";options.maxOperations=100000000;std::filesystem::create_directories(options.dataDirectory);auto run=[&](const std::string& source,bool expected=true){++checks;const auto result=runtime::execute(source,{},options);if(result.ok()!=expected){++failures;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<" @"<<d.span.offset<<": "<<d.message<<'\n';}};
run("native function [real x,real y] plane(real u,real v){return u,v;}native function [real fx,real fy,real r] flux(real u,real ux,real uy,real t,real x,real y,real strength){real D=1+strength*u*u;return D*ux,D*uy,0.0;}native function real exact(real t,real x,real y){return x+y;}native function real forcing(real t,real x,real y,real strength){return -4*strength*(x+y);}record mesh=paramesh(plane,linspace(0,1,3),linspace(0,1,3));record a=femmixed(flux,mesh,options(parameters=options(strength=1.0),forcing=forcing,forcing_parameters=options(strength=1.0),boundary_value=exact,exact=exact,order=2));record b=femmixed(flux,mesh,options(parameters=options(strength=2.0),forcing=forcing,forcing_parameters=options(strength=2.0),boundary_value=exact,exact=exact,order=2));assert(a.converged&&b.converged);assert(a.l2_error<1e-8&&b.l2_error<1e-8);assert(a.cache_keys==b.cache_keys&&b.cache_hit);assert(a.newton_iterations>1&&a.jacobian_evaluations>0);assert(a.component_offsets(1)==1&&a.component_offsets(2)==a.dofs+1);assert(norm(a.dof_values-a.dof_coordinates(:,1)-a.dof_coordinates(:,2),\"fro\")<1e-8);");
run("native function [real x,real y] plane(real u,real v){return u,v;}native function [real fx,real fy,real r] flux(real u,real ux,real uy,real t,real x,real y){return ux,uy,u;}record mesh=paramesh(plane,[0,1],[0,1]);record bad=femmixed(flux,mesh,options(orders=[1,2]));",false);
#ifdef PENTA_SOURCE_DIR
for(const auto* name:{"mixed-p1-p3-coupled-fields.p","native-quasilinear-algebra-flux.p"}){std::ifstream input(std::filesystem::path(PENTA_SOURCE_DIR)/"examples/high-order-finite-elements"/name);run(std::string((std::istreambuf_iterator<char>(input)),{}));}
#endif
std::error_code ignored;std::filesystem::remove_all(options.dataDirectory,ignored);std::cout<<checks<<" mixed H1 FEM language checks, "<<failures<<" failures\n";return failures?1:0;}
